mapper.select:
		SELECT 
		 DEAL.TRADE_ID AS tradeId,DEAL.F_TRADE_ID AS fTradeId
		FROM (
			SELECT 
			  B.TRADE_ID,
			  B.F_TRADE_ID,
			  B.FINPROD_ID,
        	  B.FINPROD_TYPE,
			  E.PORTFOLIO_ID AS PRODID
			FROM TRD_PRODUCT_DEAL B,TRD_PRODUCT_DEAL_ADD E
			WHERE B.TRADE_ID = E.TRADE_ID 
			AND B.CREATE_USER = #{createUser,jdbcType=VARCHAR}
			AND TO_CHAR(B.CREATE_TIME,'yyyyMMdd') = #{createTime,jdbcType=VARCHAR}

				AND (E.PORTFOLIO_ID IN




									) OR E.PORTFOLIO_ID IN (
									,


							#{bookSetId}


				)


				AND B.BUSI_TYPE = #{busiType,jdbcType=VARCHAR}


				AND B.BUSI_TYPE IN

			        #{busiTypes}



				AND B.PS IN

			        #{ps_is}



		      	AND B.PS NOT IN

			        #{ps_not}



		    	AND B.PS= #{ps,jdbcType=VARCHAR}


		    	AND (B.F_TRADE_ID IN


		                  null) OR B.F_TRADE_ID in ( 

		                #{obj.fTradeId}

		    	)


				AND B.PS IN

			        #{fps}



				AND B.FINPROD_TYPE =  #{finprodType,jdbcType=VARCHAR}


				AND B.TRADE_ID = B.TOTLE_TRADE_ID


				AND (B.TRADE_ID = B.TOTLE_TRADE_ID OR B.TOTLE_TRADE_ID IS NULL)


				AND B.TRADE_ID = B.TOTLE_TRADE_ID

		) DEAL
		LEFT JOIN (
		  SELECT  
		       P.FINPROD_ID,P.FINPROD_TYPE,P.PROFIT_TYPE
		       ,P.IS_CHL
	      FROM FIN_PRODUCT P

	      UNION ALL
	      SELECT PT.FINPROD_ID,PT.FINPROD_TYPE,PT.PROFIT_TYPE 
	      ,NULL AS IS_CHL
	      FROM FIN_TRADE_PRODUCT PT
	      WHERE PT.BRANCH=0

	      	AND PT.FINPROD_TYPE != 'F21'

		) PROD ON DEAL.FINPROD_ID = PROD.FINPROD_ID AND DEAL.FINPROD_TYPE = PROD.FINPROD_TYPE
		WHERE 1=1 

			AND PROD.PROFIT_TYPE = #{assetProfitType,jdbcType=VARCHAR}



				AND PROD.IS_CHL = #{IS_CHL,jdbcType=VARCHAR}


				AND (PROD.IS_CHL IS NULL OR PROD.IS_CHL = #{IS_CHL,jdbcType=VARCHAR})



			AND EXISTS (
			     SELECT * FROM (
			        SELECT A.FINPROD_ID,A.FINPROD_TYPE,A.PROFIT_TYPE FROM FIN_PRODUCT A 
			        WHERE A.FINPROD_TYPE='F16'
			        UNION 
			        SELECT D.ACCT_SUBJECT_ID,D.ACCT_SUBJECT_TYPE,D.ACCT_MODE FROM BOK_BOOKSET D
			        WHERE D.ACCT_SUBJECT_TYPE='F18' 
			     ) PROD WHERE PROD.FINPROD_ID = DEAL.PRODID
			     AND PROD.PROFIT_TYPE= #{profitType,jdbcType=VARCHAR}
			)

